import fs from 'node:fs';
import { chromium } from '/Users/noir/code/splashery/node_modules/playwright-core/index.mjs';
import { createScene } from '/Users/noir/code/splashery/src/state.js';
import { TOYS, holdsStill } from '/Users/noir/code/splashery/src/toys.js';
const out='/Users/noir/code/splashery/docs/audits/perf-2026-10';
const meta=JSON.parse(fs.readFileSync(`${out}/methodology.json`,'utf8'));
const browser=await chromium.launch({executablePath:meta.executable,headless:true,args:meta.args});
const records=[];
async function setup(def,labs=0,init=null){
 const ctx=await browser.newContext({viewport:def.viewport,deviceScaleFactor:def.deviceScaleFactor,isMobile:def.isMobile,hasTouch:def.hasTouch,reducedMotion:'no-preference',colorScheme:'light',serviceWorkers:'block'});
 const page=await ctx.newPage();const cdp=await ctx.newCDPSession(page);await cdp.send('Network.enable');await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
 const requests=[];const errors=[];
 cdp.on('Network.responseReceived',e=>{requests.push({url:e.response.url,status:e.response.status,type:e.type,headers:e.response.headers});});
 page.on('pageerror',e=>errors.push(e.message));
 await page.addInitScript(()=>performance.setResourceTimingBufferSize(2000));
 if(init)await page.addInitScript(init);
 await page.goto(`http://127.0.0.1:4173/?renderer=webgl2&profile=${def.profile}&adapt=off&labs=${labs}`,{waitUntil:'domcontentloaded'});
 await page.waitForFunction(()=>document.body.dataset.ready==='true'&&window.__splashery.player.toyInfo?.id==='cactus',{timeout:120000});
 return {ctx,page,requests,errors};
}
const observe=async page=>page.evaluate(()=>[...performance.getEntriesByType('navigation'),...performance.getEntriesByType('resource')].filter(r=>/^https?:/.test(r.name)).map(r=>({url:r.name,startMs:r.startTime,durationMs:r.duration,transferSize:r.transferSize,encodedBodySize:r.encodedBodySize,decodedBodySize:r.decodedBodySize})));
const heavy=rs=>rs.filter(r=>/vendor\/(pdfjs|omggif|onnxruntime-web|depth-anything-v2-small)/.test(r.url));
try {
 const inventory=JSON.parse(fs.readFileSync(`${out}/static-inventory.json`,'utf8'));
 for(const def of meta.definitions){
  for(const item of inventory.filter(r=>r.rigAddonSplats||r.id==='fluid-lab')){
   const toy=TOYS.find(t=>t.id===item.id);
   const {ctx,page,requests,errors}=await setup(def,toy.labs?1:0);
   const scene=createScene({seed:424242,toy:{kind:'builtin',id:toy.id}});
   if(toy.camera)scene.camera={...scene.camera,...toy.camera};
   if(holdsStill(toy))scene.autoplay.turntable=false;
   await page.evaluate(s=>window.__splashery.app.applyScene(s),scene);
   await page.waitForTimeout(1500);
   const census=await page.evaluate(()=>{
    const p=window.__splashery.player;
    const components=p.stage.app.root.findComponents('gsplat').map(c=>({entity:c.entity.name,enabled:c.enabled,entityEnabled:c.entity.enabled,resourceSplats:(c.resource||c._placement?.resource||p.stage.app.assets.get(c.asset)?.resource)?.numSplats??null}));
    return {statusSplats:p.toyInfo.splats+(p.pictures?.splats()||0),addonSplats:p.stage.toy?.addon?.resource?.numSplats??0,components,fluid:p.fluids?{mode:p.fluids.mode,...p.fluids.stats,layerCapacity:p.fluids.layer?.container?.numSplats??0}:null};
   });
   records.push({kind:'additional-splat-census',device:def.name,id:toy.id,at:new Date().toISOString(),census,expectedStaticAddon:item.rigAddonSplats??0,errors});await ctx.close();
   console.log(`Additional splats ${def.name} ${toy.id}: addon=${census.addonSplats} fluid=${census.fluid?.slots??0}`);
  }
 }
 for(const def of meta.definitions){
  for(const labs of [0,1]){
   const {ctx,page,requests,errors}=await setup(def,labs);
   await page.waitForTimeout(5000);const initial=await observe(page);
   await page.evaluate(()=>window.__splashery.app.ui.toggleGallery());
   await page.waitForTimeout(1500);const gallery=await observe(page);
   const thumbnails=await page.evaluate(async()=>{
    const images=[...document.querySelectorAll('.toy-card')].filter(c=>!c.hidden).map(c=>c.querySelector('img')).filter(Boolean);
    for(const img of images)img.loading='eager';
    await Promise.all(images.map(img=>img.decode().catch(()=>null)));
    return {cards:images.length,loaded:images.filter(i=>i.naturalWidth>0).length,failed:images.filter(i=>!i.naturalWidth).map(i=>i.src)};
   });
   await page.waitForTimeout(500);const all=await observe(page);
   records.push({kind:'gallery',device:def.name,labs:!!labs,at:new Date().toISOString(),initial,gallery,all,thumbnails,heavyAtInitial:heavy(initial),requests,errors});
   await ctx.close();console.log(`Gallery ${def.name} labs=${labs}: ${thumbnails.loaded}/${thumbnails.cards} thumbnails, initial heavy=${heavy(initial).length}`);
  }
 }
 {
  const {ctx,page,requests,errors}=await setup(meta.definitions[0],1,()=>Object.defineProperty(globalThis,'ImageDecoder',{value:undefined,configurable:true}));
  await page.waitForTimeout(1000);const before=await observe(page);
  let result;
  try {result=await page.evaluate(async()=>{
   const bytes=Uint8Array.from(atob('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'),c=>c.charCodeAt(0));
   const {openMedia}=await import('/src/media.js');const media=await openMedia(new File([bytes],'tiny.gif',{type:'image/gif'}),{profile:'low'});
   const r={kind:media.kind,count:media.count};media.close();return r;
  });}catch(e){result={error:String(e)};}
  await page.waitForTimeout(500);const after=await observe(page);
  records.push({kind:'gif-fallback',at:new Date().toISOString(),before,after,result,requests,errors});await ctx.close();console.log(`GIF fallback: ${JSON.stringify(result)}`);
 }
 {
  const {ctx,page,requests,errors}=await setup(meta.definitions[0],1);
  await page.waitForTimeout(1000);const before=await observe(page);let result;
  try {result=await page.evaluate(async()=>{
   const {loadDepthModel}=await import('/src/packs/photo-3d-depth.js');const got=await loadDepthModel();return {sessionCreated:!!got?.s};
  });}catch(e){result={error:String(e)};}
  const after=await observe(page);records.push({kind:'explicit-depth-loader',at:new Date().toISOString(),before,after,result,requests,errors});await ctx.close();console.log(`Depth loader: ${JSON.stringify(result)}`);
 }
 {
  const {ctx,page,requests,errors}=await setup(meta.definitions[0],0,()=>localStorage.setItem('splashery.sound','on'));
  await page.waitForTimeout(1000);const before=await observe(page);
  await page.evaluate(()=>window.__splashery.app.chooseToy('dice'));
  await page.waitForFunction(()=>window.__splashery.player.toyInfo?.id==='dice',{timeout:120000});await page.waitForTimeout(2000);
  const after=await observe(page);records.push({kind:'sound-enabled-dice',at:new Date().toISOString(),before,after,requests,errors});await ctx.close();console.log(`Sound-enabled dice sample requests: ${after.filter(r=>r.url.includes('/assets/sounds/')).length}`);
 }
} finally {const version=await browser.version();await browser.close();fs.writeFileSync(`${out}/site-probes.json`,JSON.stringify({browser:version,resourceTimingBufferSize:2000,source:fs.readFileSync('/tmp/splashery-site-probes.mjs','utf8'),records},null,2)+'\n');}
